import{_ as l,l as n,o as e,c as o,v as t,p,x as i,d as s,i as E,S as A}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"可积性与恢复偏好","description":"","frontmatter":{"title":"可积性与恢复偏好","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/integrability.md","filePath":"econ/integrability.md","lastUpdated":1789023840000}'),d={name:"econ/integrability.md"};function u(c,a,h,_,B,f){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="可积性与恢复偏好" tabindex="-1">可积性与恢复偏好 <a class="header-anchor" href="#可积性与恢复偏好" aria-label="Permalink to &quot;可积性与恢复偏好&quot;">​</a></h1><div class="epigraph"><p>需求作为价格的函数，何时是某一偏好的马歇尔需求？答案在斯勒茨基矩阵的对称与负半定，以及相应的可积条件。</p><footer>—— 据 Hurwicz and Uzawa, On the Integrability of Demand Functions, 1971；Mas-Colell, Whinston and Green 第 3 章整理</footer></div><p><a href="/econ/sarp-garp">上一课</a>（SARP 与 GARP）。给出了有限观测上的成对一致性。本课不重讲 WARP 的几何，也不再定义 \\(R^D\\)。缺口是：若手里是整个需求函数 \\(x(p,w)\\)，而不是几条数据，怎样还原出 \\(u\\)？WARP 不够，因为它不对称；斯勒茨基课已经预告对称性是微分形式的可积条件。本课把这条路走完，并收束「确定下的选择」这一课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>给定零次齐次、满足瓦尔拉斯定律的 \\(x(p,w)\\)，能否找到连续偏好，使其马歇尔需求正好是 \\(x\\)？局部看，这是把向量场 \\(x(p,w)\\) 积回一个值函数 \\(v(p,w)\\)，再对偶出 \\(u\\)。向量场可积，需要混合偏导相等——正是 \\(S\\) 对称。再加负半定，积出来的 \\(v\\) 才对 \\(p\\) 拟凸，对应凸偏好的支出最小化。</p><p>有限数据上的 Afriat 定理是同一问题的离散版：GARP 成立当且仅当存在一组数 \\(u^t,\\lambda^t\\gt 0\\) 满足</p> \\[u^s\\le u^t+\\lambda^t p^t\\cdot(x^s-x^t). \\]<p>这些数构成一个凹的分段线性效用，在观测点上精确生成选择。本课把 Afriat 与 Hurwicz–Uzawa 并在一起：一个是有限观测，一个是光滑需求，恢复的都是偏好，不是新的心理学。</p><h3 id="恢复的是序数偏好-不是唯一数字" tabindex="-1">恢复的是序数偏好，不是唯一数字 <a class="header-anchor" href="#恢复的是序数偏好-不是唯一数字" aria-label="Permalink to &quot;恢复的是序数偏好，不是唯一数字&quot;">​</a></h3><p>Afriat 数不唯一；光滑情形下 \\(v\\) 也只确定到单调变换。恢复成功意味着「存在某一 \\(u\\)」，不是「估计出了真实幸福」。后课期望效用会在彩票上再加公理，那是另一表示，不能把这里的 \\(u\\) 直接拿去对风险取期望。</p><p><span class="marginnote">Antonelli 矩阵是反需求的可积条件，与斯勒茨基对偶。本课用 \\(S\\)，因为上一课已经把它从支出函数里读出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光滑路线：由 \\(x\\) 构造 \\(S_{ij}=\\partial x_i/\\partial p_j+x_j\\partial x_i/\\partial w\\)。检验 \\(S\\) 对称且负半定、\\(Sp=0\\)。通过则存在支出函数（积分 \\(h=\\nabla_p e\\)），再由对偶得到 \\(u\\)。失败则不存在局部非餍足的连续凸偏好能生成这个 \\(x\\)——模型在函数层面被拒绝。</p><p>离散路线：对观测跑 GARP；通过则解 Afriat 不等式，得到一个在样本上精确、在样本外以凹包络延拓的效用。WARP 过而 GARP 不过，说明成对没问题、三条以上的链出了循环，光滑极限里往往对应 \\(S\\) 不对称。</p>',14)),(e(),p(A,null,{default:i(()=>[E(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%9C%80%E6%B1%82%E5%87%BD%E6%95%B0%E6%88%96%E6%9C%89%E9%99%90%E8%A7%82%E6%B5%8B%22%5D%20--%3E%20TEST%5B%22S%20%E5%AF%B9%E7%A7%B0%E8%B4%9F%E5%8D%8A%E5%AE%9A%20%2F%20GARP%22%5D%0A%20%20TEST%20--%3E%20OK%5B%22%E5%AD%98%E5%9C%A8%20u%EF%BC%9AAfriat%20%E6%88%96%E7%A7%AF%E5%88%86%20v%22%5D%0A%20%20TEST%20--%3E%20NO%5B%22%E4%B8%8D%E5%AD%98%E5%9C%A8%E7%90%86%E6%80%A7%E5%87%B8%E5%81%8F%E5%A5%BD%22%5D%0A%20%20OK%20--%3E%20U%5B%22%E6%81%A2%E5%A4%8D%E7%9A%84%E5%BA%8F%E6%95%B0%E6%95%88%E7%94%A8%22%5D%0A%20%20U%20--%3E%20LATER%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%E5%BA%8F%EF%BC%9A%E5%BD%A9%E7%A5%A8%E4%B8%8E%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Afriat 数不唯一，光滑 \\(v\\) 也只确定到单调变换。恢复成功意味着「存在某一 \\(u\\)」，不是「估计出了真实幸福」。下一课期望效用会在彩票上再加独立性，那是另一表示，不能把这里的 \\(u\\) 直接拿去对风险取期望。</p><p>本课不把偏微分方程的特征线推一遍。Hurwicz–Uzawa 的贡献是给出充分条件，使局部可积能延拓到全域需求。主干只需：对称 + 负半定是「需求来自偏好」的可操作判据。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可积性把消费者理论收成一个闭环。正向：偏好 → \\(u\\) → \\(x\\) → \\(S\\)。反向：数据 → WARP/GARP 或 \\(S\\) → \\(u\\)。闭环意味着后课谈税收、价格指数时，可以说「若选择来自偏好，则补偿变化用 \\(e\\) 积分」。若不可积，这些福利数没有偏好基础，只是会计。</p><p>与斯勒茨基课的衔接是：那里 \\(S\\) 的性质是定理；这里同一性质是假设，用来反推定理的前提。箭头一反，检验的地位就从「形状描述」变成「模型是否被数据允许」。</p><p><span class="marginnote">可积性不管跨期、不管风险。时间可分、期望效用，都是另加的结构。本课序在确定消费束上结束。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>恢复出的 \\(u\\) 只在观测覆盖的预算区域内可信。样本外延拓依赖凹性，不是数据。家庭加总、跨期储蓄、劳动供给若被塞进同一个 \\(x(p,w)\\)，可积失败可能只是对象切错了，不一定是「人不理性」。</p><p>下一课序改对象：备选不再是确定的 \\(x\\in\\mathbb{R}_+^n\\)，而是彩票。确定消费上的 \\(u\\) 不能直接当伯努利函数用。本课不预支独立性公理。可积性也不处理跨期可分：两个日期的需求若被当成同一期的 \\(x(p,w)\\)，对称性没有理由成立。那是宏观欧拉方程的对象，不是本课序的尾巴。</p><p>后课默认：确定需求与偏好之间可以双向行走；风险要另起表示。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光滑需求可积当且仅当斯勒茨基矩阵对称且负半定（加正则条件）。</li><li>有限观测上 GARP 等价于 Afriat 效用的存在。</li><li>恢复的是序数偏好，数字不唯一。</li><li>确定下的选择课序在此收束；风险从彩票另起。</li><li>出处：Hurwicz and Uzawa, 1971；Afriat；Mas-Colell, Whinston and Green 第 3 章。</li></ul>',12))])}const b=l(d,[["render",u]]);export{x as __pageData,b as default};
